using System;using System.Linq;using System.Collections.Generic;using System.IO;using System.Text;using Frociart;
internal static class ReferenceArrayCoreTests {
 static int checks;static string Decode(string s){return Encoding.UTF8.GetString(Convert.FromBase64String(s));}static void Check(bool b,string s){if(!b)throw new Exception(s);checks++;}
 static void Execute(Diagram d,string[] row){var r=new Interpreter(d);int at=0;for(int i=0;i<1500&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++){if(r.State==RuntimeState.WaitingForInput){Check(!r.ProvideInput("invalid_input"),"Invalid indexed input remains retryable");r.ProvideInput(row[6].Split('|')[at++]);}else if(r.State==RuntimeState.WaitingForFile)r.ProvideFile(r.PendingFile,row[7]);else r.Step();}
 Check((r.State==RuntimeState.Error)==(row[5]=="error"),row[0]+" expected="+row[5]+" actual="+r.State+" "+r.Error);Check(r.State==RuntimeState.Error||r.State==RuntimeState.Completed,"Bounded completion");Check(r.OutputText.Replace("\r\n","\n")==row[2],"Output "+row[0]+": "+r.OutputText);var root=r.CallStack.FirstOrDefault();object a;string value=root!=null&&root.Variables.TryGetValue("a",out a)?ValueFormatter.Format(a):"";Check(value==row[3],"Root reference value "+row[0]+": "+value);}
 [STAThread]static int Main(string[] args){try{string root=args[0];foreach(string line in File.ReadAllLines(Path.Combine(root,"cases.tsv"),Encoding.UTF8)){var raw=line.Split('\t');var row=new[]{raw[0]}.Concat(raw.Skip(1).Select(Decode)).ToArray();var d=FlowPseudocode.Decode(row[1]);foreach(var f in d.Functions??new List<FlowFunction>())foreach(var p in f.Parameters)p.ByReference=p.IsArray&&(row[4]=="*"||row[4].Split('|').Contains(f.Name+":"+p.Name));d.Version=FunctionModel.ProjectVersion(d.Functions);string before=Convert.ToBase64String(DiagramIO.EncodeDocument(d));Execute(d,row);Check(Convert.ToBase64String(DiagramIO.EncodeDocument(d))==before,"Runtime leaves graph unchanged");Execute(DiagramIO.Clone(d),row);Execute(FlowPseudocode.Decode(FlowPseudocode.Encode(d)),row);string file=Path.Combine(root,"pc-"+row[0]+".frociart");DiagramIO.Save(file,d);var loaded=DiagramIO.Load(file);Check(loaded.Functions.SelectMany(f=>f.Parameters).Count(p=>p.ByReference)==d.Functions.SelectMany(f=>f.Parameters).Count(p=>p.ByReference),"Optional reference flag retained");Execute(loaded,row);string counterpart=Path.Combine(root,"android-"+row[0]+".frociart");if(File.Exists(counterpart))Execute(DiagramIO.Load(counterpart),row);Console.WriteLine("PASS "+row[0]);}
 var watch=FlowPseudocode.Decode("FUNZIONE bump(v: INTERO[])\nv[0]=7\nPAUSA\nv[0]=8\nFINE FUNZIONE\na=[1,2]\nCHIAMA bump(a)");watch.Functions[0].Parameters[0].ByReference=true;watch.Version=3;var run=new Interpreter(watch);var debug=new FlowDebugger(run,watch);debug.Begin(FlowDebugger.Command.Continue);for(int i=0;i<50&&debug.Active;i++)debug.Tick();Check(debug.AtBreakpoint,"Breakpoint inside reference call");var saved=run.CallStack[0];Check(ValueFormatter.Format(saved.Variables["a"])=="[7, 2]","Caller watch updates before function returns");debug.Begin(FlowDebugger.Command.Continue);for(int i=0;i<50&&debug.Active;i++)debug.Tick();Check(ValueFormatter.Format(run.CallStack[0].Variables["a"])=="[8, 2]","Final reference update visible");Check(ValueFormatter.Format(saved.Variables["a"])=="[7, 2]","Previous watch snapshot remains immutable");
 Console.WriteLine("REFERENCE_ARRAY_PC_CORE PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
